export interface Profile {
    id: string;
    username: string;
    display_name: string;
    age?: number;
    gender?: string;
    bio?: string;
    school?: string;
    course?: string;
    year_level?: string;
    photos?: ProfilePhoto[];
    interests?: Interest[];
    created_at: string;
    updated_at: string;
}
export interface ProfilePhoto {
    id: string;
    url: string;
    thumbnail_url?: string;
    is_primary: boolean;
    sort_order: number;
}
export interface Interest {
    id: string;
    name: string;
    slug: string;
}
